/**
 * build-iot-dash.js — Generate iot-dashboard.html from live IoT Admin Console data
 * Reads /tmp/rmstatus-light/iot-admin-data.json (generated by scrape-iot-admin.js)
 */
const fs = require('fs');

const DATA_FILE = '/tmp/rmstatus-light/iot-admin-data.json';
const OUTPUT = '/tmp/rmstatus-light/iot-dashboard.html';

if (!fs.existsSync(DATA_FILE)) {
  console.error(`❌ Data file not found: ${DATA_FILE}. Run scrape-iot-admin.js first.`);
  process.exit(1);
}

const data = JSON.parse(fs.readFileSync(DATA_FILE, 'utf-8'));

const now = new Date();
const dateStr = now.toLocaleDateString('en-GB');
const timeStr = now.toLocaleTimeString('en-GB');

const errors = data.errorsWarnings || [];
const attention = data.attentionDevices || [];
const locations = data.locations || [];

function escHtml(s) {
  if (!s) return '';
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function stateClass(s) {
  const u = (s || '').toUpperCase();
  if (u === 'TRACKING') return 'tracking';
  if (u === 'READY') return 'ready';
  if (u === 'OFFLINE') return 'offline';
  if (u === 'IDLE') return 'idle';
  return '';
}

// Error rows sorted by errors (desc)
const sortedErrors = [...errors].sort((a, b) => b.errors - a.errors);
const errorRows = sortedErrors.slice(0, 12).map(d => `
  <tr><td><a class="mac" href="#">${escHtml(d.device)}</a></td>
  <td><span class="st ${stateClass(d.state)}">${escHtml(d.state)}</span></td>
  <td><span class="err">${d.errors}</span></td>
  <td><span class="${d.warnings > 0 ? 'warn' : 'no'}">${d.warnings}</span></td></tr>
`).join('\n');

// Attention rows
const attRows = attention.length > 0 ? attention.map(d => `
  <tr><td><a class="mac" href="#">${escHtml(d.device)}</a></td>
  <td><span class="st ${stateClass(d.state)}">${escHtml(d.state)}</span></td>
  <td><span class="age">${escHtml(d.lastSeen)}</span></td>
  <td>${d.cmds && d.cmds !== '0' ? `<span class="err">${escHtml(d.cmds)}</span>` : '<span class="no">0</span>'}</td>
  <td><span class="logs">Logs</span></td></tr>
`).join('\n') : '<tr><td colspan="5" style="text-align:center;color:#64748b;padding:20px">No devices need attention</td></tr>';

// Location rows
const locRows = locations.map(l => {
  const j3011Cls = l.j3011 > 0 ? 'vcnt' : 'vcnt zero';
  const jnx30Cls = l.jnx30 > 0 ? 'vcnt' : 'vcnt zero';
  const jnx42Cls = l.jnx42 > 0 ? 'vcnt' : 'vcnt zero';
  const isHighlight = l.venue.includes('Union Coop') || l.venue.includes('UMM SUQEIM') || l.venue.includes('AL WARQA');
  const vnameStyle = isHighlight ? 'style="font-weight:700"' : '';
  return `<div class="vrow"><span class="vname" ${vnameStyle}>${escHtml(l.venue)}</span>
    <span class="${j3011Cls}">${l.j3011}</span>
    <span class="${jnx30Cls}">${l.jnx30}</span>
    <span class="${jnx42Cls}">${l.jnx42}</span>
    <span class="vcnt">${l.total}</span></div>`;
}).join('\n');

const totalLocations = locations.length;
const totalErrors = data.totals?.errorsTotal || errors.length;
const totalAttention = data.totals?.attentionTotal || attention.length;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<meta http-equiv="refresh" content="600">
<title>IoT Admin Console — Dashboard</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Inter,-apple-system,BlinkMacSystemFont,sans-serif;background:#f1f5f9;color:#1e293b;min-height:100vh}
.hdr{background:#0f172a;padding:0 20px;height:48px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #1e293b}
.hdr .left{display:flex;align-items:center;gap:12px}
.hdr .menu{color:#64748b;cursor:pointer;font-size:20px;line-height:1}
.hdr h1{font-size:14px;font-weight:600;color:#e2e8f0}
.hdr h1 a{color:#e2e8f0;text-decoration:none}
.hdr .logo{display:flex;align-items:center;gap:6px;color:#94a3b8;font-size:12px;font-weight:600}
.hdr .logo img{height:20px;border-radius:3px}

.sub{padding:10px 20px;background:#fff;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between}
.sub h2{font-size:16px;font-weight:700}
.sub .refresh{display:flex;align-items:center;gap:6px;color:#64748b;font-size:12px;cursor:pointer;padding:4px 10px;border-radius:4px;border:1px solid #e2e8f0}
.sub .refresh:hover{background:#f8fafc}

.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:16px 20px}
.card{background:#fff;border-radius:8px;border:1px solid #e2e8f0;overflow:hidden}
.card.full{grid-column:1/-1}
.card h3{padding:12px 14px 8px;font-size:13px;font-weight:600;color:#475569;display:flex;align-items:center;justify-content:space-between}
.card h3 .link{font-size:11px;font-weight:400;color:#3b82f6;cursor:pointer}
.card h3 .link:hover{text-decoration:underline}

table{width:100%;border-collapse:collapse;font-size:12px}
th{padding:8px 14px;background:#f8fafc;color:#64748b;font-size:10px;text-transform:uppercase;letter-spacing:.5px;text-align:left;font-weight:600;border-bottom:1px solid #e2e8f0}
td{padding:8px 14px;border-bottom:1px solid #f1f5f9;font-size:12px}
tr:last-child td{border-bottom:none}
tr:hover{background:#f8fafc}
.mac{font-family:'SF Mono',Consolas,monospace;color:#3b82f6;font-size:11px;text-decoration:none}
.mac:hover{text-decoration:underline}
.st{font-size:11px;padding:2px 8px;border-radius:4px;font-weight:600;display:inline-block}
.st.tracking{background:#dcfce7;color:#16a34a}
.st.ready{background:#dbeafe;color:#2563eb}
.st.offline{background:#fef2f2;color:#dc2626}
.st.idle{background:#fef9c3;color:#ca8a04}
.err{color:#dc2626;font-weight:600}
.warn{color:#ca8a04;font-weight:600}
.no{color:#94a3b8}
.age{color:#64748b;font-size:11px}
.logs{color:#3b82f6;font-size:11px;cursor:pointer}
.logs:hover{text-decoration:underline}

.vrow{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;padding:8px 14px;border-bottom:1px solid #f1f5f9;font-size:12px;align-items:center}
.vrow:hover{background:#f8fafc}
.vrow.header{background:#f8fafc;color:#64748b;font-size:10px;text-transform:uppercase;letter-spacing:.5px;font-weight:600;padding:8px 14px;border-bottom:1px solid #e2e8f0}
.vname{font-weight:500}
.vcnt{text-align:center;font-weight:600;cursor:pointer;color:#3b82f6}
.vcnt.zero{color:#94a3b8;cursor:default}

.pagination{padding:10px 14px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e2e8f0;color:#64748b;font-size:11px}
.pagination .pbtn{display:flex;gap:4px}
.pagination .pbtn button{background:#fff;border:1px solid #e2e8f0;border-radius:4px;padding:4px 8px;cursor:pointer;color:#475569;font-size:11px}
.pagination .pbtn button:disabled{opacity:.4;cursor:default}
.pagination .pbtn button:hover:not(:disabled){background:#f8fafc}

.ft{text-align:center;padding:20px;color:#94a3b8;font-size:11px}

@media(max-width:768px){
  .grid{grid-template-columns:1fr;padding:12px}
}
</style>
</head>
<body>

<div class="hdr">
  <div class="left">
    <span class="menu">☰</span>
    <h1><a href="#">IOT Admin Console</a></h1>
  </div>
  <div class="logo"><img src="aioo-logo.jpg" alt="AiOO">AiOO Tech Dubai</div>
</div>

<div class="sub">
  <h2>Dashboard</h2>
  <div class="refresh">↻ Refresh</div>
</div>

<div class="grid">

  <!-- Last 4 hours errors and warnings -->
  <div class="card full">
    <h3>Last 4 hours errors and warnings</h3>
    <table>
      <tr><th>Device</th><th>State</th><th>Total errors</th><th>Warnings</th></tr>
      ${errorRows}
    </table>
    <div class="pagination">
      <span>Items per page: 12</span>
      <span>1 – ${Math.min(12, sortedErrors.length)} of ${totalErrors}</span>
      <div class="pbtn">
        <button disabled>‹</button>
        <button disabled>‹‹</button>
        <button ${sortedErrors.length <= 12 ? 'disabled' : ''}>›</button>
        <button ${sortedErrors.length <= 12 ? 'disabled' : ''}>››</button>
      </div>
    </div>
  </div>

  <!-- Devices that may need attention -->
  <div class="card full">
    <h3>Devices that may need attention <span class="link">See in devices list →</span></h3>
    <table>
      <tr><th>Device</th><th>State</th><th>Last seen</th><th>Cmds</th><th>Links</th></tr>
      ${attRows}
    </table>
    <div class="pagination">
      <span>Items per page: 12</span>
      <span>1 – ${Math.min(12, attention.length)} of ${totalAttention}</span>
      <div class="pbtn">
        <button disabled>‹</button>
        <button disabled>‹‹</button>
        <button ${attention.length <= 12 ? 'disabled' : ''}>›</button>
        <button ${attention.length <= 12 ? 'disabled' : ''}>››</button>
      </div>
    </div>
  </div>

  <!-- Device by location -->
  <div class="card full">
    <h3>Device by location</h3>
    <div class="vrow header">
      <span>Venue</span><span>J3011</span><span>JNX30</span><span>JNX42</span><span>Total Nb. of IOTs</span>
    </div>
    ${locRows}
    <div class="pagination">
      <span>Items per page: ${totalLocations}</span>
      <span>1 – ${totalLocations} of ${totalLocations}</span>
      <div class="pbtn">
        <button disabled>‹</button>
        <button disabled>‹‹</button>
        <button disabled>›</button>
        <button disabled>››</button>
      </div>
    </div>
  </div>

</div>

<div class="ft">IOT Admin Console (v4.1) · AiOO Tech Dubai © · Live data · ${dateStr} ${timeStr}</div>
</body>
</html>`;

fs.writeFileSync(OUTPUT, html);
console.log(`✅ iot-dashboard.html written (${(Buffer.byteLength(html) / 1024).toFixed(0)} KB, ${totalLocations} locations, ${attention.length} attention)`);
